import { makeButton, makeView } from "@kvisaz/phaser-common";
import { makeAlign } from "@kvisaz/phaser-sugar";
import type { SolitairesContext } from "../events";

export const screenTextStyle = {
  fontFamily: "Arial, sans-serif",
  fontSize: "26px",
  color: "#fff4d1",
};

/** Общая кнопка экранов; звук и курсор обслуживает GameCore. */
export function screenButton(context: SolitairesContext, text: string, run: () => void) {
  const { scene, events } = context;
  const button = makeView(scene, (b) => {
    const bg = b.rect({ width: 270, height: 64, color: "#d5b878" });
    const label = b.text({ text, style: { ...screenTextStyle, color: "#123b32" } });
    makeAlign((a) => a.anchor(bg).center(label));
    return b.con([bg, label]);
  });
  return makeButton({
    obj: button,
    onClick: () => {
      events.emit("uiClick");
      run();
    },
    onHover: () => events.emit("uiHover"),
    onOut: () => events.emit("uiOut"),
  });
}
