import { makeAlign } from "@kvisaz/phaser-sugar";
import type { SolitairesContext } from "./events";
import { solitaireScreens, type OpenScreen, type ScreenId } from "./screens";
import { DemoView } from "./sceneViews/DemoView/DemoView";
import { MenuView } from "./sceneViews/MenuView/MenuView";
import { SolitaireView } from "./sceneViews/SolitaireView/SolitaireView";
import { screenButton } from "./sceneViews/screenUi";

export interface StartGameOptions {
  initialScreen?: ScreenId;
  onReady?: (context: SolitairesContext, open: OpenScreen) => void;
}

/** Хранит только выбранный экран; создание и очистку сцены оставляет GameCore. */
export function createScreenFactory({ initialScreen = "menu", onReady }: StartGameOptions) {
  let screen = initialScreen;

  return (context: SolitairesContext) => {
    let active = true;
    const open: OpenScreen = (next) => {
      if (!active) return;
      active = false;
      screen = next;
      context.restartGameScene();
    };
    context.registerForSceneCleanup(() => {
      active = false;
    });

    const view =
      screen === "demo"
        ? new DemoView(context)
        : screen === "menu"
          ? new MenuView(context, open)
          : new SolitaireView(context, screen, open);

    if (screen === "demo") {
      const back = screenButton(context, context.locale.t("back_to_menu"), () => open("menu"));
      makeAlign((a) => a.anchorSceneScreen(context.scene).centerX(back).topIn(back, 32));
      context.registerForSceneCleanup(back);
    }

    const { t, lang } = context.locale;
    const titleKey =
      screen === "menu"
        ? "title"
        : screen === "demo"
          ? "demo_title"
          : solitaireScreens[screen].title;
    document.title = screen === "menu" ? t("title") : `${t(titleKey)} — ${t("title")}`;
    document.documentElement.lang = lang;
    onReady?.(context, open);
    return view;
  };
}
