import { HtmlBackground, makeButton, makeView } from "@kvisaz/phaser-common";
import { makeAlign } from "@kvisaz/phaser-sugar";
import { autoAssetsConfig } from "../../autoAssetsConfig";
import { imageAsset } from "../../assets";
import type { SolitairesContext } from "../../events";
import { solitaireIds, solitaireScreens, type OpenScreen } from "../../screens";
import { screenButton } from "../screenUi";

const fonts = autoAssetsConfig.fonts;
const layout = { buttonWidth: 680, buttonHeight: 98, buttonGap: 18, slice: 16 };
const suits = {
  klondike: "suitSpade",
  spider: "suitHeart",
  freecell: "suitClub",
  yukon: "suitDiamond",
  fortyThieves: "suitSpade",
} as const;

/** Стартовый экран: пять игр и отдельный стенд проверки стартера. */
export class MenuView {
  private readonly root: Phaser.GameObjects.Container;

  /** Собирает Classic XL из PNG и текста; интерактивность подключает makeButton. */
  constructor(context: SolitairesContext, open: OpenScreen) {
    const {
      scene,
      events,
      locale: { t },
    } = context;
    context.registerForSceneCleanup(
      new HtmlBackground({ url: autoAssetsConfig.images.backgroundCloth.url }),
    );
    const buttons = solitaireIds.map((id) => {
      const spec = solitaireScreens[id];
      const button = makeView(scene, (b) => {
        const bg = b.nine({
          ...imageAsset("buttonDefault"),
          width: layout.buttonWidth,
          height: layout.buttonHeight,
          padding: layout.slice,
        });
        const icon = b.img(imageAsset(suits[id])).setDisplaySize(32, 35);
        const label = b.text({
          text: t(spec.title),
          style: {
            fontFamily: fonts.interSemibold.fontFamily,
            fontSize: "38px",
            color: "#263b32",
          },
        });
        makeAlign((a) => {
          a.anchor(bg).leftIn(icon, 28).centerY(icon);
          a.leftIn(label, 86).centerY(label);
        });
        return b.con([bg, icon, label]);
      });
      makeButton({
        obj: button,
        onClick: () => {
          events.emit("uiClick");
          open(id);
        },
      });
      button.on("pointerover", () => events.emit("uiHover"));
      button.on("pointerout", () => events.emit("uiOut"));
      return button;
    });
    const demo = screenButton(context, t("demo_title"), () => open("demo"));
    this.root = makeView(scene, (b) => {
      const hero = b.img(imageAsset("hero02")).setDisplaySize(660, 660);
      // Диалог настроек не входит в текущую верстку: пока это только изображение.
      const settings = b.img(imageAsset("iconSettings")).setDisplaySize(128, 128);
      const title = b.text({
        text: t("title"),
        style: { fontFamily: fonts.notoSerifBold.fontFamily, fontSize: "88px", color: "#f4ebd5" },
      });
      const subtitle = b.text({
        text: t("menu_subtitle"),
        style: { fontFamily: fonts.interRegular.fontFamily, fontSize: "32px", color: "#d6e1cf" },
      });
      makeAlign((a) => a.column(buttons, layout.buttonGap));
      const choices = b.con(buttons);
      makeAlign((a) => {
        a.anchorSceneScreen(scene);
        a.leftIn(title, 120).topIn(title, 146);
        a.leftIn(subtitle, 126).topIn(subtitle, 279);
        a.leftIn(hero, 116).topIn(hero, 344);
        a.rightIn(choices, -130).topIn(choices, 240);
        a.rightIn(settings, -48).topIn(settings, 12);
        a.anchor(choices).centerX(demo).bottomTo(demo, 48);
      });
      return b.con([hero, title, subtitle, choices, settings, demo]);
    });
  }

  /** Удаляет меню при завершении Host-сцены. */
  destroy(): void {
    this.root.destroy();
  }
}
