import type { ISolitairesEvents, SolitairesContext } from "../../events";

/** Проверяет события и сервисы стартера отдельно от вёрстки стенда. */
export class DemoActions {
  counter: number;
  seconds = 0;
  eventCount = 0;
  muted = false;
  soundOn = true;
  status = "status_ready";
  private active = true;
  private statusVersion = 0;
  private pendingReward?: string;
  private static requestNumber = 0;

  /** Восстанавливает счётчик, подключает события и регистрирует очистку таймера. */
  constructor(
    private readonly context: SolitairesContext,
    private readonly refresh: () => void,
  ) {
    const { events, scene, loadedSaveData, registerForSceneCleanup } = context;
    const counter = loadedSaveData?.counter;
    this.counter =
      typeof counter === "number" && Number.isSafeInteger(counter) && counter >= 0 ? counter : 0;
    registerForSceneCleanup(
      events.on("demoIncrement", () => {
        this.eventCount++;
        void this.increment();
      }),
    );
    registerForSceneCleanup(
      events.on("demoFullscreenContinue", () => {
        this.setStatus("status_fullscreen_done");
      }),
    );
    registerForSceneCleanup(events.on("coreAdRewardedResult", (result) => this.onReward(result)));
    const timer = scene.time.addEvent({
      delay: 1000,
      loop: true,
      callback: () => {
        this.seconds++;
        refresh();
      },
    });
    registerForSceneCleanup(() => timer.remove(false));
  }

  /** Обновляет статус; версия защищает его от запоздалого результата сохранения. */
  private setStatus(key: string): number {
    this.status = key;
    this.refresh();
    return ++this.statusVersion;
  }

  /** Сохраняет через ядро и сообщает успех только после подтверждённой записи. */
  private async increment(success = "status_saved"): Promise<void> {
    const next = this.counter + this.context.config.incrementStep;
    if (!Number.isSafeInteger(next)) {
      this.setStatus("status_counter_limit");
      return;
    }
    this.counter = next;
    const version = this.setStatus("status_saving");
    try {
      const result = await this.context.saveGameData({ counter: next }, true);
      if (!this.active || version !== this.statusVersion) return;
      this.setStatus(
        result.errorMessage
          ? "status_save_failed"
          : result.skipReason || (result.timeToNextSave ?? 0) > 0
            ? "status_save_pending"
            : success,
      );
    } catch {
      if (this.active && version === this.statusVersion) this.setStatus("status_save_failed");
    }
  }

  /** Запускает декларативную цепочку fullscreen → continue, включая недоступную рекламу. */
  fullscreen(): void {
    this.setStatus("status_fullscreen_requested");
    this.context.events.emit("demoFullscreenRequest");
  }

  /** Не допускает двух ожидающих rewarded-запросов с одного стенда. */
  rewarded(): void {
    if (this.pendingReward) return;
    this.pendingReward = `solitaires-demo-${++DemoActions.requestNumber}`;
    this.setStatus("status_reward_requested");
    this.context.events.emit("coreAdRewardedRequest", {
      requestId: this.pendingReward,
      rewardId: "demo-counter",
    });
  }

  /** Начисляет награду один раз и только для подтверждённого собственного запроса. */
  private onReward(result: ISolitairesEvents["coreAdRewardedResult"]): void {
    if (result.requestId !== this.pendingReward || result.rewardId !== "demo-counter") return;
    this.pendingReward = undefined;
    if (result.rewardGranted) void this.increment("status_reward_granted");
    else this.setStatus("status_reward_failed");
  }

  /** Проверяет независимый временный mute, который не должна снимать реклама. */
  toggleMute(): void {
    this.muted = !this.muted;
    this.context.events.emit("coreSoundMuteRequest", {
      owner: "solitaires-demo",
      muted: this.muted,
    });
    this.setStatus(this.muted ? "status_muted" : "status_unmuted");
  }

  /** Проверяет постоянные настройки эффектов отдельно от временного mute. */
  toggleSound(): void {
    this.soundOn = !this.soundOn;
    this.context.events.emit("coreSoundSettingsChanged", {
      isMusicOn: false,
      isSoundOn: this.soundOn,
    });
    this.setStatus(this.soundOn ? "status_sound_on" : "status_sound_off");
  }

  /** Переключает локаль и пересоздаёт контент; URL сохраняет выбор при перезагрузке страницы. */
  toggleLanguage(): void {
    const { locale, restartGameScene } = this.context;
    locale.setLanguage(locale.lang === "ru" ? "en" : "ru");
    const url = new URL(window.location.href);
    url.searchParams.set("lang", locale.lang);
    window.history.replaceState({}, "", url);
    restartGameScene();
  }

  /** Запрещает асинхронным сохранениям обновлять уже уничтоженное представление. */
  destroy(): void {
    this.active = false;
    this.pendingReward = undefined;
  }
}
