import { makeButton, makeView } from "@kvisaz/phaser-common";
import { makeAlign } from "@kvisaz/phaser-sugar";
import type { SolitairesContext } from "../../events";
import { DemoActions } from "./DemoActions";

const layout = { cardWidth: 270, cardHeight: 330, cardGap: 24, gap: 32 };
const textStyle = { fontFamily: "Arial, sans-serif", fontSize: "24px", color: "#123b32" };

/** Пять карточек проверяют сервисы стартера, не реализуя правила пасьянсов. */
export class DemoView {
  private readonly root: Phaser.GameObjects.Container;
  private readonly actions: DemoActions;
  private status!: Phaser.GameObjects.Text;
  private metrics!: Phaser.GameObjects.Text;
  private cardRow!: Phaser.GameObjects.Container;
  private values: Array<{ text: Phaser.GameObjects.Text; bg: Phaser.GameObjects.Rectangle }> = [];

  /** Создаёт стенд и подключает реальные события и сервисы GameCore. */
  constructor(private readonly context: SolitairesContext) {
    const { scene, locale, events } = context;
    const { t } = locale;
    document.title = t("title");
    document.documentElement.lang = locale.lang;
    this.actions = new DemoActions(context, () => this.refresh());
    const a = this.actions;
    const specs = [
      { title: "card_save", button: "increment", run: () => events.emit("demoIncrement") },
      { title: "card_fullscreen", button: "show_ad", run: () => a.fullscreen() },
      { title: "card_rewarded", button: "show_reward", run: () => a.rewarded() },
      { title: "card_sound", button: "toggle_mute", run: () => a.toggleMute() },
      { title: "card_lifecycle", button: "restart", run: () => context.restartGameScene() },
    ];
    const cards = specs.map((spec) => {
      const button = this.button(t(spec.button), spec.run);
      return makeView(scene, (b) => {
        const bg = b.rect({
          width: layout.cardWidth,
          height: layout.cardHeight,
          color: "#f7f0dc",
          strokeColor: "#d5b878",
          strokeWidth: 4,
        });
        const title = b.text({ text: t(spec.title), style: textStyle });
        const value = b.text({ text: "", style: { ...textStyle, fontSize: "32px" } });
        this.values.push({ text: value, bg });
        makeAlign((align) => {
          align.anchor(bg).centerX(title).topIn(title, layout.gap);
          align.anchor(bg).centerX(button).bottomIn(button, -layout.gap);
        });
        return b.con([bg, title, value, button]);
      });
    });
    const controls = [
      this.button(t("toggle_sound"), () => a.toggleSound()),
      this.button(t("play_sound"), () => events.emit("demoClick"), false),
      this.button(t("language"), () => a.toggleLanguage()),
    ];

    this.root = makeView(scene, (b) => {
      const title = b.text({
        text: t("title"),
        style: { ...textStyle, fontSize: "64px", color: "#fff4d1" },
      });
      const description = b.text({
        text: t("demo_description"),
        style: { ...textStyle, color: "#c1d8ce" },
      });
      const style = { ...textStyle, color: "#fff4d1", align: "center", wordWrap: { width: 1440 } };
      this.status = b.text({ text: "", style });
      this.metrics = b.text({ text: "", style });
      makeAlign((align) => {
        align.row(cards, layout.cardGap);
        align.row(controls, layout.cardGap);
      });
      this.cardRow = b.con(cards);
      const toolbar = b.con(controls);
      /** Основной ряд центрируется по экрану; заголовки и панель привязаны к его границам. */
      makeAlign((align) => {
        align.anchorSceneScreen(scene).center(this.cardRow);
        align.anchor(this.cardRow).centerX(description).topTo(description, -64);
        align.anchor(description).centerX(title).topTo(title, -layout.gap);
        align.anchor(this.cardRow).centerX(toolbar).bottomTo(toolbar, 160);
      });
      return b.con([title, description, this.cardRow, this.status, this.metrics, toolbar]);
    });
    this.refresh();
  }

  /** Создаёт кнопку с проверкой звука и курсора через шину ядра. */
  private button(text: string, run: () => void, clickSound = true): Phaser.GameObjects.Container {
    const { scene, events } = this.context;
    const button = makeView(scene, (b) => {
      const bg = b.rect({ width: 238, height: 60, color: "#d5b878" });
      const label = b.text({ text, style: { ...textStyle, fontSize: "21px" } });
      makeAlign((align) => align.anchor(bg).center(label));
      return b.con([bg, label]);
    });
    return makeButton({
      obj: button,
      onClick: () => {
        if (clickSound) events.emit("demoClick");
        run();
      },
      onHover: () => events.emit("demoHover"),
      onOut: () => events.emit("demoOut"),
    });
  }

  /** Показывает фактические состояния сервисов и повторно выравнивает изменившийся текст. */
  private refresh(): void {
    const {
      locale: { t },
      adAvailability,
      scene,
      config,
    } = this.context;
    const a = this.actions;
    const values = [
      String(a.counter),
      t(adAvailability.isFullscreenAvailable() ? "available" : "unavailable"),
      t(adAvailability.isRewardedAvailable() ? "available" : "unavailable"),
      t(scene.sound.mute ? "sound_muted" : "sound_active"),
      `${a.seconds} ${t("seconds")}`,
    ];
    this.values.forEach(({ text, bg }, i) => {
      text.setText(values[i]);
      makeAlign((align) => align.anchor(bg).center(text));
    });
    this.status.setText(t(a.status));
    this.metrics.setText(
      `${t("events")}: ${a.eventCount} · ${t("step")}: ${config.incrementStep} · ${t("cleanup_hint")}`,
    );
    makeAlign((align) => {
      align.anchor(this.cardRow).centerX(this.status).bottomTo(this.status, layout.gap);
      align.anchor(this.status).centerX(this.metrics).bottomTo(this.metrics, 16);
    });
  }

  /** Инвалидирует ожидающие сохранения и удаляет объекты; ядро снимает подписки и таймер. */
  destroy(): void {
    this.actions.destroy();
    this.root.destroy();
  }
}
