import { makeView } from "@kvisaz/phaser-common";
import { makeAlign } from "@kvisaz/phaser-sugar";
import type { SolitairesContext } from "../../events";
import { solitaireScreens, type OpenScreen, type SolitaireId } from "../../screens";
import { screenButton, screenTextStyle } from "../screenUi";

/** Общая оболочка пяти пасьянсов; игровые правила подключаются отдельно. */
export class SolitaireView {
  private readonly root: Phaser.GameObjects.Container;

  /** Рисует выбранный стол, явно обозначая отсутствие игровой логики. */
  constructor(context: SolitairesContext, id: SolitaireId, open: OpenScreen) {
    const {
      scene,
      locale: { t },
    } = context;
    const spec = solitaireScreens[id];
    const back = screenButton(context, t("back_to_menu"), () => open("menu"));
    this.root = makeView(scene, (b) => {
      const title = b.text({
        text: `${spec.symbol}  ${t(spec.title)}`,
        style: { ...screenTextStyle, fontSize: "56px" },
      });
      const hint = b.text({ text: t("table_placeholder"), style: screenTextStyle });
      const slots = Array.from({ length: spec.columns }, () =>
        b.rect({
          width: 128,
          height: 184,
          color: "#1b4c40",
          strokeColor: "#799f87",
          strokeWidth: 2,
        }),
      );
      makeAlign((a) => a.row(slots, 24));
      const table = b.con(slots);
      makeAlign((a) => {
        a.anchorSceneScreen(scene).center(table);
        a.anchor(table).centerX(title).topTo(title, -96);
        a.anchor(table).centerX(hint).bottomTo(hint, 64);
        a.anchor(hint).centerX(back).bottomTo(back, 48);
      });
      return b.con([title, table, hint, back]);
    });
  }

  /** Освобождает оболочку; будущий движок партии также должен уничтожаться здесь. */
  destroy(): void {
    this.root.destroy();
  }
}
